        Util_CreateSwitch(parent, "M1 flings", m.FlingEnabled["M1"]).Changed:Connect(function(v) m.FlingEnabled["M1"] = v end)
        Util_CreateSwitch(parent, "M2 flings", m.FlingEnabled["M2"]).Changed:Connect(function(v) m.FlingEnabled["M2"] = v end)
        Util_CreateSwitch(parent, "Spike Trail flings", m.FlingEnabled["Spike Trail"]).Changed:Connect(function(v) m.FlingEnabled["Spike Trail"] = v end)
        Util_CreateSwitch(parent, "Alice's Special Hell flings", m.FlingEnabled["Alice's Special Hell"]).Changed:Connect(function(v) m.FlingEnabled["Alice's Special Hell"] = v end)
    end

    m.SaveConfig = function()
        return { FlingEnabled = m.FlingEnabled }
    end

    m.LoadConfig = function(save)
        if type(save.FlingEnabled) == "table" then
            for k, v in pairs(save.FlingEnabled) do
                if m.FlingEnabled[k] ~= nil then
                    m.FlingEnabled[k] = v
                end
            end
        end
    end

    -- ── LOCAL STATE ────────────────────────────────────────────────────────
    local baseAnims    = {}
    local actionAnims  = {}
    local animJump     = nil
    local actionStart  = {}
    local currentBase   = "idle"
    local currentAction = nil
    local wasInAir      = false
    local flingActive   = false
    local touchConns    = {}
    local allJoints     = {}
    local figureRef     = nil
    local SPEED_WALK    = 16
